        securityTab.classList.add('hidden');
      } else {
        securityBtn.className = "w-1/2 text-center py-2 text-sm font-semibold rounded-lg bg-white dark:bg-slate-900 shadow-sm text-indigo-600 dark:text-indigo-400 transition-all";
        profileBtn.className = "w-1/2 text-center py-2 text-sm font-semibold rounded-lg text-slate-500 hover:text-slate-900 dark:hover:text-white transition-all";
        securityTab.classList.remove('hidden');
        profileTab.classList.add('hidden');
      }
    }
