        <button id="dot-2" class="w-2 h-2 rounded-full bg-white/40"></button>
      </div>
    </div>
    <div class="mt-4 flex justify-between items-center px-2">
      <div>
        <h3 class="text-xs font-bold text-slate-900 dark:text-white" id="slide-title">Paradise Coasts</h3>
        <p class="text-[10px] text-slate-400 mt-0.5" id="slide-desc">Scenic aerial coastline view.</p>
      </div>
      <button id="next-btn" class="p-2 bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-xl text-slate-500 hover:text-slate-950 transition text-xs font-bold">Next &rarr;</button>
    </div>
    <script>
      const img1 = document.getElementById('slide-img-1');
      const img2 = document.getElementById('slide-img-2');
      const dot1 = document.getElementById('dot-1');
      const dot2 = document.getElementById('dot-2');
