          img1.classList.replace('opacity-0', 'opacity-100');
          img2.classList.replace('opacity-100', 'opacity-0');
          dot1.classList.replace('bg-white/40', 'bg-white');
          dot2.classList.replace('bg-white', 'bg-white/40');
          title.textContent = 'Paradise Coasts';
          desc.textContent = 'Scenic aerial coastline view.';
          index = 0;
        }
      });
