<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <script src="https://cdn.tailwindcss.com"></script>
</head>
<body class="bg-slate-50 dark:bg-slate-950 min-h-screen flex items-center justify-center p-6">
  <div class="w-full max-w-md bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-xl p-8">
    <h2 class="text-lg font-bold text-slate-900 dark:text-white">Preferences</h2>
    <p class="text-xs text-slate-500 mt-1">Manage system-level delivery channels and security scopes.</p>
    <div class="mt-8 space-y-6">
      <div class="flex items-center justify-between gap-4">
        <div>
          <span class="text-xs font-bold text-slate-900 dark:text-white block">Email Updates</span>
          <p class="text-[11px] text-slate-500 dark:text-slate-400 mt-1 leading-relaxed">Receive routine compile analytics and billing invoices directly.</p>
        </div>
        <button id="toggle-email" class="w-10 h-6 bg-indigo-600 rounded-full p-1 transition relative shrink-0" aria-checked="true">
          <div class="w-4 h-4 bg-white rounded-full transition translate-x-4"></div>
        </button>
      </div>
      <div class="flex items-center justify-between gap-4 border-t border-slate-100 dark:border-slate-800/80 pt-6">
        <div>
          <span class="text-xs font-bold text-slate-900 dark:text-white block">Push Notifications</span>
          <p class="text-[11px] text-slate-500 dark:text-slate-400 mt-1 leading-relaxed">Alert terminal endpoints during critical pipeline restarts.</p>
        </div>
        <button id="toggle-push" class="w-10 h-6 bg-slate-200 dark:bg-slate-800 rounded-full p-1 transition relative shrink-0" aria-checked="false">
          <div class="w-4 h-4 bg-white rounded-full transition translate-x-0"></div>
        </button>
      </div>
    </div>
    <script>
      function setupToggle(btnId) {
        const btn = document.getElementById(btnId);
        let active = btn.getAttribute('aria-checked') === 'true';
        btn.addEventListener('click', () => {
          active = !active;
          btn.setAttribute('aria-checked', active.toString());
          const dot = btn.firstElementChild;
          if (active) {
            btn.classList.replace('bg-slate-200', 'bg-indigo-600');
            btn.classList.replace('dark:bg-slate-800', 'bg-indigo-600');
            dot.classList.replace('translate-x-0', 'translate-x-4');
          } else {
            btn.classList.replace('bg-indigo-600', 'bg-slate-200');
            btn.classList.add('dark:bg-slate-800');
            dot.classList.replace('translate-x-4', 'translate-x-0');
          }
        });
      }
      setupToggle('toggle-email');
      setupToggle('toggle-push');
    </script>
  </div>
</body>
</html>
