<body class="bg-slate-50 dark:bg-slate-950 min-h-screen flex items-center justify-center p-6">
  <div class="w-full max-w-sm bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl shadow-xl p-8 text-center">
    <h3 class="text-lg font-bold text-slate-900 dark:text-white">Rate our platform</h3>
    <p class="text-xs text-slate-500 mt-1 leading-relaxed">Help us improve our automated design pipelines with your active review feedback.</p>
    <div class="mt-6 flex justify-center gap-2" id="stars-container">
      <button class="star-btn text-2xl text-slate-300 dark:text-slate-700 transition active:scale-90" data-val="1">★</button>
      <button class="star-btn text-2xl text-slate-300 dark:text-slate-700 transition active:scale-90" data-val="2">★</button>
      <button class="star-btn text-2xl text-slate-300 dark:text-slate-700 transition active:scale-90" data-val="3">★</button>
      <button class="star-btn text-2xl text-slate-300 dark:text-slate-700 transition active:scale-90" data-val="4">★</button>
      <button class="star-btn text-2xl text-slate-300 dark:text-slate-700 transition active:scale-90" data-val="5">★</button>
    </div>
    <form class="mt-6 space-y-4">
      <textarea rows="3" placeholder="What can we optimize?" class="w-full p-4 text-xs rounded-xl border border-slate-200 dark:border-slate-800 bg-transparent text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500" required></textarea>
      <button type="submit" class="w-full py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-semibold text-xs rounded-xl transition">Submit Review</button>
    </form>
    <script>
      const stars = document.querySelectorAll('.star-btn');
      stars.forEach(star => {
        star.addEventListener('click', () => {
          const rating = parseInt(star.getAttribute('data-val'));
          stars.forEach((s, i) => {
            if (i < rating) {
              s.classList.replace('text-slate-300', 'text-yellow-400');
              s.classList.replace('dark:text-slate-700', 'text-yellow-400');
            } else {
              s.classList.replace('text-yellow-400', 'text-slate-300');
              s.classList.add('dark:text-slate-700');
            }
          });
        });
      });
    </script>
  </div>
</body>
</html>
