</head>
<body class="bg-slate-100 dark:bg-slate-950 min-h-screen relative overflow-hidden">
  <div class="p-6">
    <button id="open-drawer" class="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold rounded-lg">Open Settings</button>
  </div>
  <div id="drawer-backdrop" class="fixed inset-0 bg-slate-950/40 hidden z-40"></div>
  <aside id="drawer-panel" class="fixed right-0 top-0 bottom-0 w-80 bg-white dark:bg-slate-900 shadow-2xl border-l border-slate-200 dark:border-slate-800 translate-x-full transition-transform duration-300 ease-in-out z-50 p-6 flex flex-col">
    <div class="flex justify-between items-center">
      <h3 class="font-bold text-slate-900 dark:text-white">Panel Settings</h3>
      <button id="close-drawer" class="text-xs font-bold text-slate-400 hover:text-slate-600">Close</button>
    </div>
  </aside>
  <script>
    const openBtn = document.getElementById('open-drawer');
    const closeBtn = document.getElementById('close-drawer');
    const drawer = document.getElementById('drawer-panel');
    const backdrop = document.getElementById('drawer-backdrop');
    function toggleDrawer() {
      drawer.classList.toggle('translate-x-full');
      backdrop.classList.toggle('hidden');
    }
    openBtn.addEventListener('click', toggleDrawer);
    closeBtn.addEventListener('click', toggleDrawer);
    backdrop.addEventListener('click', toggleDrawer);
  </script>
</body>
</html>
